from pathlib import Path
import html, json, re
root=Path('/mnt/data/dash-work')
base='https://dashh.ir'
css='/style.css'
nav='''<div class="nav-shell"><header class="wrap nav"><a class="brand" href="/" aria-label="دش">د<span>ش</span></a><nav class="navlinks" aria-label="ناوبری اصلی"><a href="/#moments">چه زمانی؟</a><a href="/#how">چطور کار می‌کند؟</a><a href="/faq.html">سؤالات متداول</a><a href="/about.html">درباره دش</a><a href="/chekhabar.html">چخبر؟</a></nav><a class="btn primary nav-cta" href="/request.html">درخواست راننده</a></header></div>'''
footer='''<footer class="footer"><div class="wrap footer-top"><div><strong class="footer-brand">دش</strong><div>راننده جایگزین برای خودروی شخصی</div></div><div class="footerlinks"><a href="/about.html">درباره دش</a><a href="/faq.html">سؤالات متداول</a><a href="/replacement-driver.html">راننده جایگزین</a><a href="/chekhabar.html">چخبر؟</a><a href="/request.html">درخواست راننده</a></div></div><div class="wrap" style="margin-top:20px">© دش — راننده جایگزین برای خودروی شخصی</div></footer>'''

def page(slug,title,desc,kicker,lead,sections,sources,links):
    ld={"@context":"https://schema.org","@type":"Article","headline":title,"description":desc,"inLanguage":"fa-IR","author":{"@type":"Organization","name":"دش"},"publisher":{"@type":"Organization","name":"دش"},"mainEntityOfPage":{"@type":"WebPage","@id":f"{base}/{slug}.html"}}
    body=f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{html.escape(title)} | دش</title><meta name="description" content="{html.escape(desc)}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#f5f8fa"><link rel="canonical" href="{base}/{slug}.html"><link rel="icon" href="/favicon.png" type="image/png"><link rel="stylesheet" href="{css}"><script type="application/ld+json">{json.dumps(ld,ensure_ascii=False)}</script></head><body><a class="skip-link" href="#main-content">رفتن به محتوای اصلی</a>{nav}<main id="main-content"><div class="wrap breadcrumbs">دش ← چخبر؟ ← {html.escape(kicker)}</div><article class="article-page wrap"><header class="article-hero"><div class="eyebrow">{html.escape(kicker)}</div><h1>{html.escape(title)}</h1><p class="lead">{html.escape(lead)}</p></header><div class="article-layout"><div class="article-body">'''
    for h,p in sections:
        body+=f'<section><h2>{html.escape(h)}</h2>{p}</section>'
    body+='''<section class="notice"><strong>دش چه کمکی می‌کند؟</strong><p>اگر خودرو برای خودت است اما در یک موقعیت مشخص نمی‌خواهی یا نمی‌توانی رانندگی کنی، می‌توانی برای همان خودرو درخواست راننده جایگزین ثبت کنی. دش نقش سکوی واسط برای هماهنگی کاربر و راننده را دارد؛ محدوده، ظرفیت و شرایط خدمت باید هنگام درخواست بررسی شود.</p><a class="v5-inline" href="/request.html">درخواست راننده <span>←</span></a></section>'''
    body+='<section><h2>منابع این مطلب</h2><ul class="source-list">'+''.join(f'<li><a href="{u}" rel="nofollow noopener" target="_blank">{html.escape(n)}</a></li>' for n,u in sources)+'</ul></section></div><aside class="article-aside"><div class="panel"><strong>مطالب مرتبط</strong>'+''.join(f'<a class="pill" href="/{s}.html">{html.escape(t)}</a>' for s,t in links)+'</div><div class="panel"><strong>اگر خودت نباید رانندگی کنی</strong><p>خودروی خودت را نگه دار؛ برای مسیرت راننده بخواه.</p><a class="btn primary" href="/request.html">درخواست راننده</a></div></aside></div></article></main>{footer}</body></html>'''
    (root/f'{slug}.html').write_text(body,encoding='utf-8')

page('fatigue-driving','خستگی و خواب‌آلودگی هنگام رانندگی؛ چه زمانی نباید پشت فرمان بنشینیم؟','نشانه‌های خستگی و خواب‌آلودگی هنگام رانندگی را بشناسید و بدانید چه زمانی بهتر است رانندگی را متوقف کنید و برای خودروی شخصی راننده جایگزین بخواهید.','ایمنی رانندگی','خستگی فقط حس خواب‌آلودگی نیست؛ می‌تواند توجه، واکنش و تصمیم‌گیری را ضعیف کند. اگر احساس می‌کنی برای رانندگی آماده نیستی، ادامه دادن مسیر با زور و قهوه راه‌حل مطمئنی نیست.',[
('خستگی رانندگی چه نشانه‌هایی دارد؟','<p>خمیازه مکرر، سنگینی پلک، از دست دادن تمرکز، فراموش کردن چند کیلومتر اخیر مسیر، انحراف از خط یا جا ماندن از تابلوها از هشدارهای مهم‌اند. NHTSA نیز توصیه می‌کند در صورت بروز نشانه‌های خواب‌آلودگی، رانندگی ادامه پیدا نکند.</p>'),
('آیا باز کردن پنجره یا بلند کردن صدای موسیقی کافی است؟','<p>نه. این کارها ممکن است احساس بیداری را برای مدت کوتاهی تغییر دهند، اما خواب کافی و توقف ایمن راهکار اصلی برای مقابله با خواب‌آلودگی است. اگر پشت فرمان هستی و خوابت می‌آید، به محل امن برو و رانندگی را متوقف کن.</p>'),
('اگر خودرو خودم را دارم اما نمی‌توانم رانندگی کنم چه؟','<p>اینجاست که «راننده جایگزین» با تاکسی فرق دارد. در مدل دش، قرار نیست خودرو را عوض کنی؛ خودرو همان خودروی تو می‌ماند و راننده برای آن مسیر هماهنگ می‌شود.</p>'),
('چرا خستگی در دش یک موضوع ایمنی است، نه فقط راحتی؟','<p>هدف دش این نیست که خستگی را با یک ترفند پنهان کند؛ هدف این است که وقتی رانندگی انتخاب مناسبی نیست، یک گزینه جایگزین برای ادامه مسیر با خودروی شخصی وجود داشته باشد.</p>')],
[('NHTSA — Drowsy Driving', 'https://www.nhtsa.gov/risky-driving/drowsy-driving'),('NHTSA — Safe Driving Tips', 'https://www.nhtsa.gov/ten-tips-for-safe-driving')],
[('replacement-driver','راننده جایگزین چیست؟'),('when-not-to-drive','چه زمانی نباید رانندگی کنیم؟'),('medication-and-driving','دارو و رانندگی')])

page('after-surgery','بعد از عمل چه زمانی نباید خودمان رانندگی کنیم؟','راهنمای عمومی برای افرادی که بعد از جراحی یا ترخیص، خودرو دارند اما هنوز شرایط رانندگی ندارند؛ همراه با نکات ایمنی و راهکار راننده جایگزین.','بعد از عمل','بعد از جراحی، مسئله فقط درد نیست؛ نوع عمل، داروها، هوشیاری و دستور پزشک می‌تواند روی توانایی رانندگی اثر بگذارد. تصمیم نهایی درباره زمان بازگشت به رانندگی باید با نظر پزشک یا تیم درمانی باشد.',[
('آیا می‌توانم بعد از عمل خودم از بیمارستان رانندگی کنم؟','<p>معمولاً نباید فرض کرد که بلافاصله بعد از جراحی می‌توان خودتان رانندگی کرد. NHS می‌گوید بیماران معمولاً بعد از عمل نمی‌توانند خودشان رانندگی کنند و باید برای برگشت به خانه وسیله‌ای غیر از رانندگی شخصی در نظر بگیرند.</p>'),
('چه چیزهایی می‌تواند رانندگی را بعد از عمل دشوار کند؟','<p>درد، محدودیت حرکت، کاهش تمرکز، ضعف یا سرگیجه و اثر بعضی داروها می‌توانند روی کنترل خودرو اثر بگذارند. علاوه بر این، بعضی عمل‌ها حرکت گردن، شانه، پا یا واکنش سریع را محدود می‌کنند.</p>'),
('اگر ماشین خودم کنار بیمارستان است چه؟','<p>داشتن خودرو به معنی آماده بودن برای رانندگی نیست. اگر پزشک یا شرایط جسمی اجازه رانندگی نمی‌دهد، می‌توانی به‌جای کنار گذاشتن خودرو، برای همان خودرو راننده جایگزین درخواست کنی.</p>'),
('دش جای توصیه پزشک نیست','<p>دش سرویس هماهنگی راننده است، نه سرویس پزشکی. اگر درباره زمان بازگشت به رانندگی تردید داری، اول از پزشک یا مرکز درمانی خودت راهنمایی بگیر.</p>')],
[('NHS — After surgery: Transport home','https://www.nhs.uk/tests-and-treatments/having-surgery/afterwards/')],
[('medication-and-driving','دارو و رانندگی'),('replacement-driver','راننده جایگزین چیست؟'),('driving-while-sick','رانندگی هنگام بیماری')])

page('medication-and-driving','دارو و رانندگی؛ کدام عوارض می‌توانند پشت فرمان مشکل‌ساز شوند؟','بعضی داروهای نسخه‌ای و بدون نسخه می‌توانند باعث خواب‌آلودگی، سرگیجه، تاری دید یا اختلال هماهنگی شوند. قبل از رانندگی برچسب و دستور دارو را بررسی کنید.','دارو و رانندگی','اینکه یک دارو قانونی یا نسخه‌ای است، به معنی بی‌اثر بودن آن بر رانندگی نیست. اگر دارویی روی هوشیاری یا هماهنگی تو اثر می‌گذارد، رانندگی می‌تواند انتخاب نامناسبی باشد.',[
('چه عوارضی برای رانندگی مهم‌اند؟','<p>خواب‌آلودگی، سرگیجه، تاری دید، کند شدن واکنش یا اختلال هماهنگی از عوارضی هستند که می‌توانند رانندگی را تحت تأثیر قرار دهند. CDC و NHTSA هر دو درباره اثر برخی داروهای نسخه‌ای و بدون نسخه بر رانندگی هشدار داده‌اند.</p>'),
('اگر تازه دارویی را شروع کرده‌ام چه کنم؟','<p>بروشور دارو و هشدارهای مربوط به رانندگی را بخوان و اگر درباره اثر آن مطمئن نیستی از پزشک یا داروساز بپرس. برای داروهای جدید، خودت را با حدس و تجربه پشت فرمان آزمایش نکن.</p>'),
('دارو + الکل چرا مهم‌تر می‌شود؟','<p>برخی مواد می‌توانند اثر یکدیگر را تشدید کنند. بنابراین اگر دارویی مصرف کرده‌ای که ممکن است هوشیاری را کاهش دهد، ترکیب آن با الکل می‌تواند خطر را بیشتر کند.</p>'),
('اگر خودرو دارم اما نباید رانندگی کنم','<p>در این شرایط، راننده جایگزین می‌تواند مسئله «خودرو دارم ولی رانندگی نمی‌کنم» را حل کند؛ بدون اینکه مجبور باشی برای هر مسیر خودرو را کنار بگذاری.</p>')],
[('CDC — Impaired Driving','https://www.cdc.gov/impaired-driving/about/index.html'),('NHTSA — Drug-Impaired Driving','https://www.nhtsa.gov/risky-driving/drug-impaired-driving')],
[('fatigue-driving','خستگی و خواب‌آلودگی'),('replacement-driver','راننده جایگزین چیست؟'),('after-surgery','بعد از عمل')])

page('drinking-and-driving','بعد از مصرف الکل می‌شود با خودروی خودمان برگردیم؟','بعد از مصرف الکل، رانندگی ایمن انتخاب مناسبی نیست. راهکار ایمن این است که راننده هوشیار انتخاب شود یا از گزینه حمل‌ونقل جایگزین استفاده شود.','الکل و رانندگی','اگر الکل مصرف کرده‌ای، روی اینکه «حالم خوب است» یا «فقط یک مسیر کوتاه است» حساب نکن. اختلال رانندگی می‌تواند قبل از آنکه فرد خودش شدت آن را تشخیص دهد شروع شود.',[
('بعد از مصرف الکل چرا نباید پشت فرمان نشست؟','<p>الکل می‌تواند توجه، قضاوت، هماهنگی و زمان واکنش را مختل کند. CDC توصیه می‌کند اگر فرد الکل یا مواد مصرف کرده است، برای برگشت برنامه‌ای داشته باشد که نیاز به رانندگی خودش نداشته باشد.</p>'),
('قهوه یا دوش سرد اثر الکل را برای رانندگی خنثی می‌کند؟','<p>نه. احساس هوشیاری بیشتر به معنی بازگشت توانایی رانندگی نیست. اگر نوشیده‌ای، راهکار امن این است که رانندگی نکنی و گزینه جایگزین داشته باشی.</p>'),
('اگر خودرو خودم را با خودم برده‌ام چه؟','<p>در چنین موقعیتی یکی از تفاوت‌های مهم دش این است که سرویس برای خودروی شخصی تو طراحی شده است؛ یعنی می‌توانی به‌جای رها کردن خودرو، در صورت فعال بودن سرویس، برای همان خودرو راننده جایگزین درخواست کنی.</p>'),
('یک نکته حقوقی مهم','<p>این مطلب درباره ایمنی است و جایگزین مشاوره حقوقی درباره قوانین محل زندگی نیست. قوانین مرتبط با الکل و رانندگی بسته به کشور و حوزه قضایی متفاوت‌اند.</p>')],
[('CDC — What You Can Do to Prevent Impaired Driving','https://www.cdc.gov/impaired-driving/what-you-can-do/index.html'),('NHTSA — Drunk Driving','https://www.nhtsa.gov/risky-driving/drunk-driving')],
[('replacement-driver','راننده جایگزین چیست؟'),('safe-return-home','چطور سالم به خانه برگردیم؟'),('when-not-to-drive','چه زمانی نباید رانندگی کنیم؟')])

page('replacement-driver','راننده جایگزین چیست؟ تفاوت راننده جایگزین، راننده در اختیار و تاکسی','تفاوت سه مدل را ساده و دقیق ببینید: در تاکسی خودرو متعلق به سرویس است؛ در راننده جایگزین، خودرو مال شماست و راننده جای آن را می‌راند.','راننده جایگزین','اگر سؤال تو این است که «ماشین خودم را دارم، ولی خودم نمی‌توانم رانندگی کنم؛ چه کار کنم؟» مفهوم راننده جایگزین دقیقاً برای همین مسئله است.',[
('راننده جایگزین یعنی چه؟','<p>راننده جایگزین فردی است که برای یک مسیر یا موقعیت مشخص، به‌جای مالک یا استفاده‌کننده اصلی خودرو پشت فرمان همان خودرو می‌نشیند. بنابراین چیزی که جایگزین می‌شود «راننده» است، نه «خودرو».</p>'),
('راننده در اختیار چه فرقی دارد؟','<p>راننده در اختیار معمولاً برای یک بازه زمانی مشخص و چند توقف یا مأموریت در اختیار مشتری است. راننده جایگزین بیشتر به یک نیاز مشخص گره می‌خورد: خودت خودرو را داری اما در آن زمان نمی‌خواهی یا نمی‌توانی رانندگی کنی.</p>'),
('دش با تاکسی چه تفاوتی دارد؟','<p>در تاکسی اینترنتی، سرویس با خودروی سرویس تو را جابه‌جا می‌کند. در دش، خودرو متعلق به خود توست و راننده برای همان خودرو هماهنگ می‌شود. این تفاوت، هسته مدل دش است.</p>'),
('اعتماد در راننده جایگزین چرا مهم است؟','<p>چون کلید و کنترل یک خودروی شخصی به فرد دیگری سپرده می‌شود. بنابراین فرایندهایی مثل احراز هویت راننده، بررسی صلاحیت رانندگی، تطبیق هویت هنگام تحویل خودرو و پشتیبانی در سفر باید شفاف باشند.</p>')],
[('دش — درباره سرویس','https://dashh.ir/about.html')],
[('after-surgery','بعد از عمل'),('fatigue-driving','خستگی و خواب‌آلودگی'),('driving-while-sick','رانندگی هنگام بیماری')])

page('elderly-driver','برای سالمندانی که نباید رانندگی کنند، با خودروی شخصی چه کنیم؟','اگر یکی از والدین یا اعضای خانواده خودرو دارد اما به دلایل جسمی یا شرایط مسیر نباید رانندگی کند، راننده جایگزین می‌تواند یک گزینه برای ادامه جابه‌جایی با همان خودرو باشد.','والدین و سالمندان','گاهی مسئله این نیست که سالمند دیگر خودرو ندارد؛ مسئله این است که رانندگی برایش مناسب نیست، اما خودرو و مقصد هنوز سر جای خود هستند.',[
('چه زمانی بهتر است درباره رانندگی سالمند دوباره فکر کنیم؟','<p>هر تغییر قابل‌توجه در دید، واکنش، تمرکز، توان حرکتی یا شرایط پزشکی می‌تواند دلیل خوبی برای گفت‌وگو با پزشک و خانواده درباره ایمنی رانندگی باشد. این تصمیم باید فردمحور و بدون برچسب‌زدن باشد.</p>'),
('آیا تنها راه‌حل، گرفتن خودرو از سالمند است؟','<p>نه لزوماً. بسته به شرایط، ممکن است گزینه‌هایی مثل رانندگی یکی از اعضای خانواده، تاکسی یا راننده جایگزین مناسب‌تر باشد. هدف باید حفظ استقلال همراه با ایمنی باشد.</p>'),
('دش چه نقشی دارد؟','<p>اگر خودرو همچنان مورد نیاز است اما رانندگی برای صاحب خودرو مناسب نیست، دش می‌تواند برای هماهنگی راننده جایگزین برای همان خودرو استفاده شود؛ البته فعال بودن سرویس و شرایط سفر باید هنگام درخواست بررسی شود.</p>')],
[('NHTSA — Safe Driving Tips','https://www.nhtsa.gov/ten-tips-for-safe-driving')],
[('replacement-driver','راننده جایگزین چیست؟'),('driving-while-sick','رانندگی هنگام بیماری'),('request','درخواست راننده')])

# fix bad link slug in one related set
p=root/'elderly-driver.html'; s=p.read_text(); s=s.replace('href="/request.html"','href="/request.html"'); p.write_text(s)
